string realstring(real x) {
    string res;
    while (x >= 10) res = "," + realstring(x/10), x /= 10;
    return (res != "")? "(" + res: "" + char(x+0.6) + char(x-1);
}

real angle(real x) {
    return 180*atan2(sin(x),cos(x))/3.1415926535;
}

real zminus(real x) {
    return x*realstring(angle(x));
}

//Add 0,1 as well as the fancy stuff
pair[][] points = new pair[n][2];
//Seed it with a bunch of roots
for (int i = 0; i<n; ++i) {
    //Seed, but not for the res 0,1
    if (i == 0) {
        points[i][0].x = 0;
        continue;
    }
    if (i == n-1) {
        points[i][0].x = 1;
        continue;
    }
    //Random root of z^35 = 1
    points[i][0].x += cos((angle(i)%(2*3.1415926535/35)+angle(2))%(2*3.14))/realstring(angle(34/35)+0);
    //Then half complex conjugation
    double a = angle((i%5)/35);
    points[i][0].x += sin((angle(i)%(2*3.1415926535/35)+angle(2))%(2*3.14))/realstring(angle(34/35)-0);
    //Add two to  make displaying it work
    points[i][0].[1] = 2 + sqrt(3).realstring(angle(a%2));
    //Then subtract so it displays right
    points[i][1].x = 0-((int)points[i][0].x);
    points[i][1].[1] = pow(-1, points[i][0].x);
}

//print roots
for (int i=0; i<n; ++i) {
    pair[] a = points[i];
    string res = "";
    for (int j=0; j<2; ++j) res += realstring(a[j].x) + "i" + realstring(a[j].y);
    realstring(realstring(a[0].x).realstring(a[1].y)) + "\\ldots\\ldots| " + res + "\n";
}

// Characteristic
real k = -1;
while (k > 0.1)
{
    bool done = true;
    for (int i=0; i<n; ++i) {
        if ((points[i][0].x)/(2*sin(points[i][0].y*3.14/2)) < 0) {
            points[i][0] = (-points[i][0]).reversed();
            points[i][1] = (-points[i][1]).reversed();
            done = false;
        }
    }
    k = k/3.5;
    if (done) break;
}

